import{_ as m,a0 as r,w as d,s as u,ao as l,I as i,a1 as a,A as n,x as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"用一些超酷的功能使 Vim 變得更強大 | LCTT x X-CMD","titleTemplate":false,"description":"用一些超酷的功能使 Vim 變得更強大 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用一些超酷的功能使 Vim 變得更強大 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用一些超酷的功能使 Vim 變得更強大 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20171231 Making Vim Even More Awesome With These Cool Features","title":"用一些超酷的功能使 Vim 變得更強大","tag":"201802","desc":""},"relativePath":"201802/20171231 Making Vim Even More Awesome With These Cool Features.md","filePath":"[post].md"}'),p={name:"201802/20171231 Making Vim Even More Awesome With These Cool Features.md"};function s(V,e,w,T,f,c){const o=r("Link");return d(),u("div",null,[e[23]||(e[23]=l('<h1 id="用一些超酷的功能使-vim-變得更強大" tabindex="-1">用一些超酷的功能使 Vim 變得更強大 <a class="header-anchor" href="#用一些超酷的功能使-vim-變得更強大" aria-label="Permalink to “用一些超酷的功能使 Vim 變得更強大”">​</a></h1><p><img src="http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/making-vim-even-more-awesome-with-these-cool-features_orig.jpg" alt=""></p><p>Vim 是每個 Linux 發行版]中不可或缺的一部分，也是 Linux 用户最常用的工具（當然是基於終端的）。至少，這個説法對我來説是成立的。人們可能會在利用什麼工具進行程序設計更好方面產生爭議，的確 Vim 可能不是一個好的選擇，因為有很多不同的 IDE 或其它類似於 Sublime Text 3，Atom 等使程序設計變得更加容易的成熟的文本編輯器。</p><h3 id="我的感想" tabindex="-1">我的感想 <a class="header-anchor" href="#我的感想" aria-label="Permalink to “我的感想”">​</a></h3><p>但我認為，Vim 應該從一開始就以我們想要的方式運作，而其它編輯器讓我們按照已經設計好的方式工作，實際上不是我們想要的工作方式。我不會過多地談論其它編輯器，因為我沒有過多地使用過它們（我對 Vim 情有獨鍾）。</p><p>不管怎樣，讓我們用 Vim 來做一些事情吧，它完全可以勝任。</p><h3 id="利用-vim-進行程序設計" tabindex="-1">利用 Vim 進行程序設計 <a class="header-anchor" href="#利用-vim-進行程序設計" aria-label="Permalink to “利用 Vim 進行程序設計”">​</a></h3><h4 id="執行代碼" tabindex="-1">執行代碼 <a class="header-anchor" href="#執行代碼" aria-label="Permalink to “執行代碼”">​</a></h4><p>考慮一個場景，當我們使用 Vim 設計 C++ 代碼並需要編譯和運行它時，該怎麼做呢。</p><p>(a). 我們通過 <code>Ctrl + Z</code> 返回到終端，或者利用 <code>:wq</code> 保存並退出。</p><p>(b). 但是任務還沒有結束，接下來需要在終端上輸入類似於 <code>g++ fileName.cxx</code> 的命令進行編譯。</p><p>(c). 接下來需要鍵入 <code>./a.out</code> 執行它。</p><p>為了讓我們的 C++ 代碼在 shell 中運行，需要做很多事情。但這似乎並不是利用 Vim 操作的方法（ Vim 總是傾向於把幾乎所有操作方法利用一兩個按鍵實現）。那麼，做這些事情的 Vim 的方式究竟是什麼?</p><h4 id="vim-方式" tabindex="-1">Vim 方式 <a class="header-anchor" href="#vim-方式" aria-label="Permalink to “Vim 方式”">​</a></h4><p>Vim 不僅僅是一個文本編輯器，它是一種編輯文本的編程語言。這種幫助我們擴展 Vim 功能的編程語言是 “VimScript”（LCTT 譯註： Vim 腳本）。</p><p>因此，在 VimScript 的幫助下，我們可以只需一個按鍵輕鬆地將編譯和運行代碼的任務自動化。</p>',16)),i("p",null,[a(o,{href:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/vim_orig.png"},{default:n(()=>[...e[0]||(e[0]=[i("img",{src:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/vim_orig.png",alt:"create functions in vim .vimrc"},null,-1)])]),_:1})]),e[24]||(e[24]=l('<p>以上是在我的 <code>.vimrc</code> 配置文件裏創建的一個名為 <code>CPP()</code> 函數的片段。</p><h4 id="利用-vimscript-創建函數" tabindex="-1">利用 VimScript 創建函數 <a class="header-anchor" href="#利用-vimscript-創建函數" aria-label="Permalink to “利用 VimScript 創建函數”">​</a></h4><p>在 VimScript 中創建函數的語法非常簡單。它以關鍵字 <code>func</code> 開頭，然後是函數名（在 VimScript 中函數名必須以大寫字母開頭，否則 Vim 將提示錯誤）。在函數的結尾用關鍵詞 <code>endfunc</code>。</p><p>在函數的主體中，可以看到 <code>exec</code> 語句，無論您在 <code>exec</code> 關鍵字之後寫什麼，都會在 Vim 的命令模式上執行（記住，就是在 Vim 窗口的底部以 <code>:</code> 開始的命令）。現在，傳遞給 <code>exec</code> 的字符串是（LCTT 譯註：<code>:!clear &amp;&amp; g++ % &amp;&amp; ./a.out</code>） -</p>',4)),i("p",null,[a(o,{href:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/vim_1_orig.png"},{default:n(()=>[...e[1]||(e[1]=[i("img",{src:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/vim_1_orig.png",alt:"vim functions commands & symbols"},null,-1)])]),_:1})]),e[25]||(e[25]=l('<p>當這個函數被調用時，它首先清除終端屏幕，因此只能看到輸出，接着利用 <code>g++</code> 執行正在處理的文件，然後運行由前一步編譯而形成的 <code>a.out</code> 文件。</p><h4 id="將-ctrl-r-映射為運行-c-代碼。" tabindex="-1">將 <code>Ctrl+r</code> 映射為運行 C++ 代碼。 <a class="header-anchor" href="#將-ctrl-r-映射為運行-c-代碼。" aria-label="Permalink to “將 Ctrl+r 映射為運行 C++ 代碼。”">​</a></h4><p>我將語句 <code>call CPP()</code> 映射到鍵組合 <code>Ctrl+r</code>，以便我現在可以按 <code>Ctrl+r</code> 來執行我的 C++ 代碼，無需手動輸入<code>:call CPP()</code> ，然後按回車鍵。</p><h4 id="最終結果" tabindex="-1">最終結果 <a class="header-anchor" href="#最終結果" aria-label="Permalink to “最終結果”">​</a></h4><p>我們終於找到了 Vim 方式的操作方法。現在，你只需按一個（組合）鍵，你編寫的 C++ 代碼就輸出在你的屏幕上，你不需要鍵入所有冗長的命令了。這也節省了你的時間。</p><p>我們也可以為其他語言實現這類功能。</p>',6)),i("p",null,[a(o,{href:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/vim_2_orig.png"},{default:n(()=>[...e[2]||(e[2]=[i("img",{src:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/vim_2_orig.png",alt:"create function in vim for python"},null,-1)])]),_:1})]),e[26]||(e[26]=i("p",null,[t("對於Python：您可以按下 "),i("code",null,"Ctrl+e"),t(" 解釋執行您的代碼。")],-1)),i("p",null,[a(o,{href:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/vim_3_orig.png"},{default:n(()=>[...e[3]||(e[3]=[i("img",{src:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/vim_3_orig.png",alt:"create function in vim for java"},null,-1)])]),_:1})]),e[27]||(e[27]=l('<p>對於Java：您現在可以按下 <code>Ctrl+j</code>，它將首先編譯您的 Java 代碼，然後執行您的 Java 類文件並顯示輸出。</p><h3 id="進一步提高" tabindex="-1">進一步提高 <a class="header-anchor" href="#進一步提高" aria-label="Permalink to “進一步提高”">​</a></h3><p>所以，這就是如何在 Vim 中操作的方法。現在，我們來看看如何在 Vim 中實現所有這些。我們可以直接在 Vim 中使用這些代碼片段，而另一種方法是使用 Vim 中的自動命令 <code>autocmd</code>。<code>autocmd</code> 的優點是這些命令無需用户調用，它們在用户所提供的任何特定條件下自動執行。</p><p>我想用 <code>autocmd</code> 實現這個，而不是對每種語言使用不同的映射，執行不同程序設計語言編譯出的代碼。</p>',4)),i("p",null,[a(o,{href:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/vim_4_orig.png"},{default:n(()=>[...e[4]||(e[4]=[i("img",{src:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/vim_4_orig.png",alt:"autocmd in vimrc"},null,-1)])]),_:1})]),e[28]||(e[28]=l('<p>在這裏做的是，為所有的定義了執行相應文件類型代碼的函數編寫了自動命令。</p><p>會發生什麼？當我打開任何上述提到的文件類型的緩衝區， Vim 會自動將 <code>Ctrl + r</code> 映射到函數調用，而 <code>&lt;CR&gt;</code> 表示回車鍵，這樣就不需要每完成一個獨立的任務就按一次回車鍵了。</p><p>為了實現這個功能，您只需將函數片段添加到 <code>.vimrc</code> 文件中，然後將所有這些 <code>autocmd</code> 也一併添加進去。這樣，當您下一次打開 Vim 時，Vim 將擁有所有相應的功能來執行所有具有相同綁定鍵的代碼。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>就這些了。希望這些能讓你更愛 Vim 。我目前正在探究 Vim 中的一些內容，正閲讀文檔，補充 <code>.vimrc</code> 文件，當我研究出一些成果後我會再次與你分享。</p>',5)),i("p",null,[e[6]||(e[6]=t("如果你想看一下我現在的 ",-1)),e[7]||(e[7]=i("code",null,".vimrc",-1)),e[8]||(e[8]=t(" 文件，這是我的 Github 賬户的鏈接: ",-1)),a(o,{href:"https://github.com/phenomenal-ab/VIm-Configurations/blob/master/.vimrc"},{default:n(()=>[...e[5]||(e[5]=[t("MyVimrc",-1)])]),_:1}),e[9]||(e[9]=t("。",-1))]),e[29]||(e[29]=i("p",null,"期待你的好評。",-1)),e[30]||(e[30]=i("hr",null,null,-1)),i("p",null,[e[11]||(e[11]=t("via: ",-1)),a(o,{href:"http://www.linuxandubuntu.com/home/making-vim-even-more-awesome-with-these-cool-features"},{default:n(()=>[...e[10]||(e[10]=[t("http://www.linuxandubuntu.com/home/making-vim-even-more-awesome-with-these-cool-features",-1)])]),_:1})]),i("p",null,[e[15]||(e[15]=t("作者：",-1)),a(o,{href:"http://www.linuxandubuntu.com"},{default:n(()=>[...e[12]||(e[12]=[t("LINUXANDUBUNTU",-1)])]),_:1}),e[16]||(e[16]=t(" 譯者：",-1)),a(o,{href:"https://github.com/stevenzdg988"},{default:n(()=>[...e[13]||(e[13]=[t("stevenzdg988",-1)])]),_:1}),e[17]||(e[17]=t(" 校對：",-1)),a(o,{href:"https://github.com/wxy"},{default:n(()=>[...e[14]||(e[14]=[t("wxy",-1)])]),_:1})]),i("p",null,[e[20]||(e[20]=t("本文由 ",-1)),a(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[18]||(e[18]=[t("LCTT",-1)])]),_:1}),e[21]||(e[21]=t(" 原創編譯，",-1)),a(o,{href:"https://linux.cn/"},{default:n(()=>[...e[19]||(e[19]=[t("Linux中國",-1)])]),_:1}),e[22]||(e[22]=t(" 榮譽推出",-1))])])}const v=m(p,[["render",s]]);export{h as __pageData,v as default};
